// Saga: run steps in order; on failure run compensations in reverse.
const steps = [
  { name: "reserve stock",     run: () => true,  undo: () => "release stock" },
  { name: "authorize payment", run: () => true,  undo: () => "void authorization" },
  { name: "book shipment",     run: () => false, undo: () => "cancel shipment" }, // fails
];

function runSaga(steps) {
  const done = [];
  for (const s of steps) {
    if (s.run()) {
      console.log("ok:    " + s.name);
      done.push(s);
    } else {
      console.log("FAIL:  " + s.name + " -> compensating");
      // compensate completed steps in reverse order
      for (const d of done.reverse()) console.log("undo:  " + d.undo());
      return "ABORTED";
    }
  }
  return "COMPLETED";
}
console.log("result:", runSaga(steps));
